class RemoveDuplicates {
  public int solve(int[] arr) {
    int s = 0, w = 0;
    while (s < arr.length) {
      boolean mustKeep = s == 0 || arr[s] != arr[s - 1];
      if (mustKeep) {
        arr[w] = arr[s];
        w++;
      }
      s++;
    }
    return w;
  }
}

